"""Crater rooms: rock walls and glowing crystals instead of mine carts, rails and timber supports."""
import sys, pathlib
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
from patch import Patch
p = Patch(); rep = p.rep
rep('rows:["#########D##########","#pppppppzzzpppppppp#","#..................#","#...r..........r...#","#..................#","#..c...........c...#","#..................#","#..................#","#..................#","#########E##########"],\n  spawns:{entry:[9,8,\'up\'],back:[9,2,\'down\']},',
    'rows:["#########D##########","########zzz#########","#..................#","#...m..........m...#","#..................#","#..................#","#..................#","#.m................#","#..................#","#########E##########"],\n  spawns:{entry:[9,8,\'up\'],back:[9,2,\'down\']},')
rep('"#p......c..c......p#","#..................#","#________kk________#"', '"##.........m......##","#..................#","#________kk________#"')
rep('"#.c..............c.#","#..................#","#########E##########"],\n  spawns:{fromWall', '"#..............m...#","#..................#","#########E##########"],\n  spawns:{fromWall')
rep('"#pppppp......pp|...#"', '"#######......##|...#"')
rep('"#..c...........c...#","#..................#","#..................#","#########E##########"],\n  spawns:{fromPool', '"#..............m...#","#..................#","#..................#","#########E##########"],\n  spawns:{fromPool')
